# ── Test rapido ──────────────────────────────────────────────────────────────
if __name__ == '__main__':
    m = MODELS['LAI']
    Xt = m['Xtrain']
    al = m['alpha_coefficients']
    mx = m['mx']
    sx = m['sx']
    he = m['hypell']
    hs = m['hypsig']
    xd = m['XDXprecalc']
    mm = m['meanmodel']

    def predict(px_raw):
        px = (px_raw / 10000.0 - mx) / sx * he
        px2 = (px_raw / 10000.0 - mx) / sx
        PtTPt = np.sum(px * px2, axis=1) * (-0.5)
        PtTDX = Xt @ px.T
        arg1 = np.exp(PtTPt[0]) * hs
        kstar = np.exp(PtTDX - xd[:, None] * 0.5)
        pred = (kstar[:, 0] @ al) * arg1 + mm
        return float(max(pred, 1e-5))

    px_veg = np.array([[300, 500, 400, 1000, 2500, 3200, 3500, 3600, 1800, 900]])
    px_suelo = np.array([[1200, 1400, 1600, 1800, 2000, 2100, 2200, 2300, 2500, 2400]])
    lv = predict(px_veg)
    ls = predict(px_suelo)
    print(f'LAI vegetacion: {lv:.3f}  (esperado ~2-5)')
    print(f'LAI suelo:      {ls:.3f}  (esperado ~0.1-1.0)')
    print('TEST OK' if abs(lv - ls) > 0.3 else 'TEST FALLO: valores iguales')
